output_text:
[
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "Shopping carts are prohibited in one-cell-wide shelf-lined aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_narrow_with_cart",
    "text": "Agents must not enter a single-file shelf aisle while still pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileShelfAisle": {
          "pre": {
            "not": "singleFileShelfAisle"
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "enterSingleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_narrow_pick",
    "text": "After taking an item from a single-file shelf aisle without the cart, the agent is obliged to retrieve the cart before leaving.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "pickupCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "singleFileShelfAisle",
          {
            "not": "hasCart"
          },
          "INTERACT"
        ]
      },
      "discharge": "pickupCart"
    }
  },
  {
    "id": "return_to_aisle_mouth_after_narrow_excursion",
    "text": "When an agent is in a single-file shelf aisle without a cart, they are obliged to return to the wide aisle mouth where carts can be parked.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "singleFileShelfAisle",
          {
            "not": "hasCart"
          }
        ]
      },
      "discharge": "cartParkingMouth"
    }
  },
  {
    "id": "no_abandon_cart_except_transfer_or_narrow",
    "text": "Agents should not be away from their cart except at the entrance cart bay, at a cart-parking aisle mouth, or inside a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "entranceCartBay": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "noCartAllowedZone": {
          "or": [
            "entranceCartBay",
            "cartParkingMouth",
            "singleFileShelfAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "not": "noCartAllowedZone"
          }
        ]
      }
    }
  },
  {
    "id": "interact_only_at_shelf_or_cart_zone",
    "text": "Interactions are only permitted next to shelves or at recognized cart-transfer locations.",
    "abstraction": {
      "state_properties": {
        "entranceCartBay": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartTransferZone": {
          "or": [
            "entranceCartBay",
            "cartParkingMouth"
          ]
        },
        "validInteractionPlace": {
          "or": [
            "adjShelf",
            "cartTransferZone"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          {
            "not": "validInteractionPlace"
          }
        ]
      }
    }
  },
  {
    "id": "cart_transfer_only_at_designated_zones",
    "text": "Picking up or dropping off a cart is only permitted at the entrance cart bay or at a wide aisle mouth serving a narrow shelf aisle.",
    "abstraction": {
      "state_properties": {
        "entranceCartBay": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartTransferZone": {
          "or": [
            "entranceCartBay",
            "cartParkingMouth"
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "pickupCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "or": [
              "dropCart",
              "pickupCart"
            ]
          },
          {
            "not": "cartTransferZone"
          }
        ]
      }
    }
  },
  {
    "id": "one_way_no_west_movement",
    "text": "The supermarket circulation rule prohibits westward movement, so agents should continue generally eastward toward the exit.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "W"
    }
  }
]
